window.products.push({"id":1152985,"name":"Plymouth 7' Round Braided Rug in Red/Olive","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61vdPVwOwWL._AC_.jpg","description":"7 foot round room sized rug compliments all decors. Banded premium tubular braided rug enhances both contemporary and traditional room decors. The 20 inch by 30 inch small rug photo shown on the product page is intended to depict color and texture only, and not the number of actual colored bands or rows that will be used or shape. To achieve larger sizes, it is necessary to increase the number of rows of braid and repeat the color scheme. Please remember that color interpretation is dependent on factors like cyberspace transmission and the color variances inherent to computer monitors and internet devices. Available in Chestnut Brown, Brown, Red Olive, Light Rose, Burgundy, Blue Mist, Midnight Blue, Hunter Green, Country Green, Wine, Dark Claret Red and Ponderosa Pine.","images":["https://m.media-amazon.com/images/I/61vdPVwOwWL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Constitution Rugs","source_asin":"B01D5I5HOC","category_path":"Home & Kitchen"},"sku":"BM-1152985","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01D5I5HOC","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01D5I5HOC","price_pending":true,"merchant_ready":false});
